import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.D7WGirly.js";const y=JSON.parse('{"title":"Hybrid payload specification","description":"","frontmatter":{},"headers":[],"relativePath":"payload-format.md","filePath":"payload-format.md"}'),s={name:"payload-format.md"};function o(r,e,d,c,p,l){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="hybrid-payload-specification" tabindex="-1">Hybrid payload specification <a class="header-anchor" href="#hybrid-payload-specification" aria-label="Permalink to &quot;Hybrid payload specification&quot;">​</a></h1><p><code>encryptLarge</code> uses a random 32-byte AES key, a random 12-byte IV, and AES-256-GCM with a 16-byte authentication tag. Only the AES key is encrypted using RSA-OAEP. Fields are base64 strings separated by colons, not one base64 encoding of the complete payload.</p><h2 id="legacy" tabindex="-1">Legacy <a class="header-anchor" href="#legacy" aria-label="Permalink to &quot;Legacy&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>encryptedKey:iv:tag:ciphertext</span></span></code></pre></div><p>Legacy payloads always use RSA-OAEP/SHA-1 and have no additional authenticated data. They remain the default output when neither <code>oaepHash</code> nor <code>payloadVersion</code> is supplied. Empty plaintext has an empty final field. Readers accept whitespace and omitted padding in standard legacy base64, while rejecting invalid punctuation and base64url encodings.</p><h2 id="version-1" tabindex="-1">Version 1 <a class="header-anchor" href="#version-1" aria-label="Permalink to &quot;Version 1&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>encrypt-rsa:v1:RSA-OAEP-SHA1+A256GCM:encryptedKey:iv:tag:ciphertext</span></span>
<span class="line"><span>encrypt-rsa:v1:RSA-OAEP-SHA256+A256GCM:encryptedKey:iv:tag:ciphertext</span></span></code></pre></div><p>The exact UTF-8 header preceding the four encoded fields is AES-GCM additional authenticated data. This binds the format version and algorithm identifier to the ciphertext. Stripping the header, changing the suite, or changing encrypted data causes decryption to fail. v1 requires canonical padded standard base64, with an empty ciphertext field allowed.</p><p><code>{ payloadVersion: &#39;v1&#39; }</code> selects the first suite. <code>{ oaepHash: &#39;sha256&#39; }</code> selects the second and implies v1. Explicit legacy/SHA-256 encryption is rejected. Decryption determines the hash from the recognized suite; an explicit <code>oaepHash</code> argument must match. Unsupported versions or suites are rejected, with no fallback to another algorithm.</p><p>Both readers check decoded IV12/tag16 before RSA decryption and AES key32 after RSA unwrapping. The encrypted AES-key field length follows the RSA modulus, so it is not fixed at 256 bytes. The parser requires exactly four legacy fields or seven v1 fields. Wrong keys and GCM authentication failures reject without releasing plaintext.</p><h2 id="rollout" tabindex="-1">Rollout <a class="header-anchor" href="#rollout" aria-label="Permalink to &quot;Rollout&quot;">​</a></h2><p>Upgrade all readers before enabling v1 writers. Older versions of the library can read only the legacy four-field format. Existing valid legacy payloads remain decryptable. Shortened tags, nonstandard IV lengths, and AES-128/192 payloads are rejected because they do not conform to this package&#39;s generated AES-256-GCM format.</p><p>A signature is separate from a hybrid payload. GCM authenticates the encrypted data under its AES key; anyone possessing the recipient&#39;s public key can create a new valid encrypted message. Use trusted RSA-PSS signatures when sender authentication is required.</p>`,13)])])}const u=a(s,[["render",o]]);export{y as __pageData,u as default};
